#include "unity.h"
#include "header.h"
#include "helpers.h"
#include "malloc_wrap.h"

void setUp(void) { }
void tearDown(void) {
    malloc_reset();
}

void unit_test_shrink_array_malloc_failure(void) {
    /* Path 2: ptr != NULL, cap >= 2, newCap <= 0 (so newCap becomes 1),
     * malloc for temp fails, return NULL.
     * We need a valid stack pointer and cap >= 2, but cap/2 <= 0.
     * This happens when cap == 1? Wait, cap must be >=2 per condition.
     * Let's examine: cap >= 2, newCap = cap/2. For newCap <= 0, cap must be 0 or negative,
     * but cap >=2 prevents that. Actually newCap <= 0 can't happen with cap >=2.
     * Looking at path: "newCap <= 0" branch is taken, then "newCap = 1".
     * So we need cap such that cap/2 <= 0, but cap >=2? That's impossible.
     * Wait, maybe the condition is (newCap <= 0) which is false for cap >=2,
     * so we take the other branch (MERGE). Path says: "STATEMENT | (newCap <= 0) --> MERGE"
     * That means the condition is false, we skip the "newCap = 1" block.
     * So we need cap >=2 and newCap > 0 (i.e., cap >=2). Let's pick cap = 2, newCap = 1.
     * Actually cap=2 gives newCap=1 which is >0, so condition false, we go to MERGE.
     * That matches path: we evaluate condition, it's false, go to merge.
     * Then malloc for temp fails.
     * So we need a valid stack with some elements, cap=2, and malloc failure.
     */
    DArrayStack *stack = create_stack(2);
    TEST_ASSERT_NOT_NULL(stack);
    /* Push one element so top is 0 */
    int push_result = push(stack, 42);
    TEST_ASSERT_EQUAL_INT(0, push_result); /* top index after push */

    /* The stack now has capacity 2, top=0, arrPtr allocated.
     * We will call shrink_array with cap=2 (current capacity).
     * The function will compute newCap = 1, allocate temp of size 1.
     * We want that malloc to fail.
     * How many allocations so far? create_stack does 2 allocations (struct + array).
     * So we need to fail the third allocation (the temp inside shrink_array).
     */
    malloc_fail_after(2); /* Let first 2 allocations succeed, fail the 3rd */

    DArrayStack *result = shrink_array(stack, 2);
    TEST_ASSERT_NULL(result);
    /* The function should have returned NULL, but the original stack pointer
     * and its arrPtr should still be valid (malloc failed, no free occurred).
     * We should still be able to free the stack.
     */
    TEST_ASSERT_NOT_NULL(stack);
    TEST_ASSERT_NOT_NULL(stack->arrPtr);
    /* Verify stack integrity: capacity unchanged (2), top unchanged (0) */
    TEST_ASSERT_EQUAL_INT(2, stack->capacity);
    TEST_ASSERT_EQUAL_INT(0, stack->top);

    /* Cleanup */
    free_stack(stack);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_shrink_array_malloc_failure);
    return UNITY_END();
}

